import { Outlet } from "@remix-run/react";
import {
  AdminFeatureLock,
  useAdminFeatureAccess,
} from "@/components/orderly/AdminFeatureLock";
import { PageShell } from "@/components/orderly/PageShell";
import { useTranslation } from "@/i18n";

export default function PermissionlessListingLayout() {
  const { t } = useTranslation();
  const { hasAdminFeatureAccess, lockProps } = useAdminFeatureAccess();

  if (!hasAdminFeatureAccess) {
    return (
      <PageShell pageTitle={t("navigation.permissionlessListing")}>
        <AdminFeatureLock {...lockProps} />
      </PageShell>
    );
  }

  return <Outlet />;
}
